-- Versioned six-district dataset. Sources and synthetic assumptions live beside every row.
-- Seed matches catalog/districts-v2.json; historical simulation snapshots are never rewritten.
CREATE TABLE akim.districts (
    id VARCHAR(32) PRIMARY KEY,
    model_version VARCHAR(64) NOT NULL,
    sort_order SMALLINT NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL,
    population_share NUMERIC(8,6) NOT NULL CHECK (population_share > 0 AND population_share <= 1),
    metrics JSONB NOT NULL CHECK (jsonb_typeof(metrics) = 'object'),
    baseline_score NUMERIC NOT NULL CHECK (baseline_score BETWEEN 0 AND 100),
    data_provenance JSONB NOT NULL CHECK (jsonb_typeof(data_provenance) = 'object')
);

